c1.hand_verify:
cloc --json app bootstrap config database routes resources/js \
  | php -r '$s=json_decode(stream_get_contents(STDIN))->SUM;
      printf("owned diff: %d lines across %d files\n",$s->code,$s->nFiles);'

c3.hand_verify:
git log --no-merges --pretty=format:'@%an' --name-only -- '*.php' \
  | awk '/^@/ {au=substr($0,2); next}
         NF {ch[$0]++; if (!seen[$0","au]++) auth[$0]++}
         END {for (f in ch) if (auth[f]==1) print ch[f], f}' \
  | sort -rn | head
